('usage_milestone', 'Milestone de Uso', 'Parabéns, {{recipientName}}! 🎉 Você atingiu {{milestone}} usos', '<html><body style="font-family:-apple-system,BlinkMacSystemFont,''Segoe UI'',sans-serif;max-width:600px;margin:0 auto;padding:20px;color:#334155"><h1 style="color:#1e40af">Parabéns, {{recipientName}}! 🎉</h1><p>Você atingiu <strong>{{milestone}} usos</strong> das nossas ferramentas! Isso mostra dedicação com sua jornada profissional.</p><p>Continue assim — cada uso te aproxima mais do seu objetivo de trabalhar nos EUA.</p><p><a href="https://hub.euanapratica.com/dashboard" style="display:inline-block;background:#2563eb;color:white;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:600">Continuar Usando</a></p>{{trackingPixel}}<hr style="border:none;border-top:1px solid #e2e8f0;margin:32px 0"><p style="font-size:12px;color:#94a3b8;text-align:center"><a href="{{unsubscribeLink}}" style="color:#94a3b8">Cancelar inscrição</a></p></body></html>', '["{{recipientName}}","{{milestone}}","{{trackingPixel}}","{{unsubscribeLink}}"]'::JSONB, 'campaign', 'Celebração de marcos de uso (5, 10, 25)', true)

